package com.quincaisoft.company.web;import com.quincaisoft.company.api.*;import org.springframework.web.bind.annotation.*;import org.springframework.security.access.prepost.PreAuthorize;import java.util.*;@RestController public class CompanyController{private final CompanyService service;public CompanyController(CompanyService service){this.service=service;}@GetMapping("/api/v1/companies")@PreAuthorize("isAuthenticated()")public List<CompanyService.Item> list(){return service.list();}}